export function notificationPermission({consent,channel,category,now=Date.now()}={}){if(!consent||consent.revokedAt)return {allow:false,reason:'NO_CONSENT'};if(consent.expiresAt&&Number(consent.expiresAt)<=now)return {allow:false,reason:'CONSENT_EXPIRED'};if(!(consent.channels||[]).includes(channel))return {allow:false,reason:'CHANNEL_DISABLED'};if(consent.categories&&!(consent.categories||[]).includes(category))return {allow:false,reason:'CATEGORY_DISABLED'};return {allow:true,reason:'CONSENT_OK'}}
